        <Message
            at="2026-10-07T18:58:30.229155Z"
        >
            <Origin>01a117ba-f2c0-7099-a2dc-e9c81e4ff6f5</Origin>
            <Speaker>$[[ Claude ]]( Dougs Claude )</Speaker>
            <Paragraph>Если воля детей реально соблюдается и это задокументировано, сценарий выглядит так:</Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    1. Пристав возбуждает производство.
                </Word> Здесь у него нет выбора: если исполнительный лист оформлен правильно, он обязан это сделать. По
                существу на этом этапе он ничего не оценивает.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    2. Вам приходит постановление и 5 дней на добровольное исполнение.
                </Word> Скорее всего, через Госуслуги.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    3. Пристав выясняет, препятствуете ли вы общению.
                </Word> Это его единственная задача. Заставить детей общаться он не может и не должен. Поскольку вы с детьми
                за границей, прийти к вам он не может, поэтому запросит у вас письменные объяснения. Вы отвечаете письменно
                и прикладываете:
            </Paragraph>
            <Paragraph>
                <List />
                <Line>
                    решение с выделенными оговорками («с учетом мнения несовершеннолетних» и разъяснение «не может быть
                    осуществлено помимо их воли»);
                </Line>
                <Line>доказательство, что канал связи организован и Максим о нём знает;</Line>
                <Line>сообщения детей, написанные ими самими;</Line>
                <Line>
                    заключение психолога о том, что отношение детей к отцу сформировано их собственным опытом, а не влиянием
                    матери.
                </Line>
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    4. Пристав принимает решение.
                </Word> Здесь два варианта:
            </Paragraph>
            <Paragraph>
                <List />
                <Line>
                    <Word>
                        <Bold />
                        Он признаёт, что препятствий нет.
                    </Word> Штрафа и ограничения выезда не будет. Производство может остаться открытым (решение о порядке
                    общения действует долго), но без санкций. Это наиболее вероятный исход при хорошей документации.
                </Line>
                <Line>
                    <Word>
                        <Bold />
                        Он формально решает, что вы препятствуете.
                    </Word> Например, решит, что раз дети за границей, отец вообще лишён общения, или что дети «настроены»
                    матерью. Тогда возможен протокол по ст. 5.35 и ограничение выезда. Оба шага можно обжаловать, и ваши
                    документы будут основой обжалования.
                </Line>
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Слабое место — слова «я не могу увидеть детей».
                </Word> Это аргумент не о воле детей, а о расстоянии. Решение даёт ему каждую вторую субботу «в районе
                проживания детей». Чтобы закрыть эту дыру, достаточно письменно сказать: «Вы можете приехать и встретиться с
                детьми в районе их проживания по графику, если они согласятся». Тогда «не могу увидеть» превращается в «дети
                не хотят», а это уже защищено решением. Минус в том, что ему придётся назвать хотя бы город. Это решение за
                вами.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Про сообщения детей.
                </Word> Пристав не сможет поговорить с ними лично, поэтому их записки он может счесть недостаточными для
                детей 9 и 11 лет. Свежее заключение русскоязычного психолога в Грузии сделает позицию гораздо прочнее, чем
                одни сообщения.
            </Paragraph>
            <Paragraph>
                Итог: при соблюдённой воле детей и хорошей фиксации пристав, скорее всего, санкций не применит. Полной
                гарантии нет, потому что многое зависит от конкретного пристава.
            </Paragraph>
        </Message>
