        <Message
            at="2026-10-08T03:50:39.208329Z"
        >
            <Origin>01a119a2-2c87-73a7-835a-daae29b11324</Origin>
            <Speaker>$[[ Claude ]]( Dougs Claude )</Speaker>
            <Action>
                Searched the web for “114-ФЗ статья 7 отказ в оформлении паспорта ограничен в праве на выезд статья 15
                текст”
            </Action>
            <Paragraph>Да, прямые нормы есть. Вот цепочка из трёх звеньев.</Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    1. Закон о выезде (114-ФЗ), ст. 15, подп. 5.
                </Word> Гражданин временно ограничен в праве на выезд, если он «уклоняется от исполнения обязательств,
                наложенных на него судом», до исполнения обязательств либо до достижения согласия сторонами. Именно через
                эту норму действует ограничение, которое выносит пристав по ст. 67 закона об исполнительном производстве.
                Текст подп. 5 привожу по памяти, но формулировка стандартная.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    2. Административный регламент МВД по выдаче загранпаспортов, п. 52.1.1.
                </Word> Это прямое основание для отказа: основаниями для отказа в оформлении паспорта являются установление
                в соответствии со статьей 15 Федерального закона от 15 августа 1996 г. N 114-ФЗ обстоятельств, влекущих
                временное ограничение права гражданина Российской Федерации на выезд из Российской Федерации. Тот же пункт
                отдельно называет основанием и несогласие законного представителя на выезд ребёнка. Это объясняет, почему
                паспорт Диме заблокирован.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    3. Процедура отказа.
                </Word> Регламент описывает, что при отказе сотрудник фиксирует статью Федерального закона N 114-ФЗ, на
                основании которой ограничено право гражданина на выезд из Российской Федерации, основание и срок
                ограничения, дату и регистрационный номер решения об ограничении. То есть отказ выдаётся письменно, с
                конкретным основанием, и его можно обжаловать.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Практика.
                </Word> Такие положения регламента оспаривали в Верховном суде (в том числе в 2016 году). Заявитель
                утверждал, что временное ограничение выезда не должно мешать выдаче паспорта, но, судя по материалам, норма
                об отказе продолжает действовать.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Две честные оговорки:
                </Word>
            </Paragraph>
            <Paragraph>
                <List />
                <Line>
                    Приведённый регламент — это регламент МВД. За границей паспорт оформляет МИД через Секцию интересов по
                    своему регламенту. Основание отказа в нём, насколько я знаю, то же самое, потому что оно вытекает
                    напрямую из ст. 15 закона 114-ФЗ. Но текст регламента МИД я не проверял.
                </Line>
                <Line>
                    Отказ возможен только если ограничение <Word>
                        <Bold />
                        уже вынесено
                    </Word> на момент проверки. Пока его нет, оснований для отказа нет. Поэтому ваш расчёт на скорость
                    подачи верный.
                </Line>
            </Paragraph>
        </Message>
