        <Message
            at="2026-10-08T06:22:40.173487Z"
        >
            <Origin>385412ee-f2c4-4f45-a3ca-1ce1eec1dd0e</Origin>
            <Speaker>$[[ Claude ]]( Dougs Claude )</Speaker>
            <Action>Used WebSearch</Action>
            <Action>Used WebFetch</Action>
            <Paragraph>
                Я проверил, и <Word>
                    <Bold />
                    я был неправ
                </Word>. Вот что говорят правила.
            </Paragraph>
            <Heading>Что такое штамп о гражданстве</Heading>
            <Paragraph>
                Это отметка на <Word>
                    <Bold />
                    обороте свидетельства о рождении
                </Word>, подтверждающая, что ребёнок — гражданин РФ. Форма утверждена Приказом МИД РФ от 22.03.2024 № 5206:
                это синий или чёрный штамп размером 6 на 10 см, в котором указаны основание приобретения гражданства, дата и
                номер решения, название ведомства, подпись должностного лица и гербовая печать. С 12 апреля 2026 года
                действует обновлённая форма: вместо даты и номера решения указываются реквизиты нормативного акта.
            </Paragraph>
            <Heading>Где я ошибся</Heading>
            <Paragraph>
                Я написал, что свидетельство, в котором оба родителя указаны гражданами РФ, само подтверждает гражданство
                ребёнка. <Word>
                    <Bold />
                    Это не так.
                </Word> Гражданство детей до 14 лет подтверждается по Указу Президента № 889 от 22.11.2023 одним из
                способов:
            </Paragraph>
            <Paragraph>
                <List />
                <Line>загранпаспортом ребёнка;</Line>
                <Line>сведениями о ребёнке в паспорте родителя;</Line>
                <Line>
                    <Word>
                        <Bold />
                        свидетельством о рождении с отметкой о гражданстве.
                    </Word>
                </Line>
            </Paragraph>
            <Paragraph>
                Сведения о гражданстве родителей в свидетельстве — это <Word>
                    <Bold />
                    основание
                </Word> для того, чтобы поставить штамп, а не замена ему.
            </Paragraph>
            <Heading>Нужен ли он вашим детям</Heading>
            <Paragraph>
                Для оформления <Word>
                    <Bold />
                    загранпаспорта ребёнку младше 14 лет
                </Word> без штампа не обойтись. Исключение: для детей, родившихся до 26.10.2023 (ваши дети), штамп не
                обязателен, если гражданство подтверждено действующим загранпаспортом, оформленным ранее, или записью в
                паспорте родителей.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Практический вывод:
                </Word> если у Кати действующий загранпаспорт, ей штамп, скорее всего, не нужен. <Word>
                    <Bold />
                    Диме для нового паспорта он, вероятно, нужен
                </Word>, если у него нет действующего загранпаспорта и он не вписан в ваш паспорт.
            </Paragraph>
            <Paragraph>
                В России штамп ставят бесплатно и в день обращения. За границей это делает консульство, то есть Секция
                интересов.
            </Paragraph>
            <Heading>Какой блок выбрать в «Консул Прайм»</Heading>
            <Paragraph>
                Ни один из видимых на скриншоте блоков не называется прямо «отметка о гражданстве». Прокрутите страницу
                вниз: возможно, такая услуга есть отдельно. Если нет, напишите им в WhatsApp: «Нужна отметка о гражданстве
                на свидетельства о рождении двух детей до 14 лет, оба родителя граждане РФ, дети родились в России. Какую
                услугу выбрать?» Скорее всего, они направят на «Проверку наличия гражданства», но лучше уточнить, чтобы не
                платить за лишнее.
            </Paragraph>
            <Paragraph>
                Source: <Word>
                    <Reference>https://www.v2b.ru/articles/shtamp-o-grazhdanstve-rebenka-v-2024-godu/</Reference>
                    Время Бухгалтера: штамп о гражданстве ребенка в 2026 году
                </Word>
            </Paragraph>
        </Message>
