        <Message
            at="2026-10-08T09:11:50.146731Z"
        >
            <Origin>9156c61b-a059-4230-b74c-23df6bb46c08</Origin>
            <Speaker>$[[ Claude ]]( Dougs Claude )</Speaker>
            <Action>Used WebSearch</Action>
            <Paragraph>Да, такая норма есть. Вот три уровня, от самого сильного к вспомогательному.</Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    1. Указ Президента РФ от 22.11.2023 № 889 «Вопросы гражданства Российской Федерации»
                </Word> Утверждённое им Положение о порядке рассмотрения вопросов гражданства РФ содержит <Word>
                    <Bold />
                    раздел XIV «Документы, удостоверяющие наличие гражданства Российской Федерации»
                </Word>. Официальный сайт Социального фонда России так пересказывает перечень по Закону № 138-ФЗ и Указу №
                889: первым в нём идёт <Word>
                    <Bold />
                    паспорт гражданина РФ, в том числе удостоверяющий личность гражданина РФ за пределами территории РФ
                </Word>, то есть загранпаспорт. Номер пункта в разделе XIV для взрослых я дословно не видел. По соседним
                пунктам о детях (173–175) это, вероятно, <Word>
                    <Bold />
                    п. 172
                </Word>, но перед ссылкой лучше сверить.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    2. Федеральный закон от 28.04.2023 № 138-ФЗ «О гражданстве Российской Федерации»
                </Word> Это базовый закон о гражданстве. Перечень документов детализирован в Указе № 889, который принят во
                исполнение этого закона. Ст. 27 того же закона определяет, что за рубежом делами о гражданстве ведают
                посольства и консульства.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    3. Федеральный закон от 15.08.1996 № 114-ФЗ «О порядке выезда из Российской Федерации и въезда в Российскую Федерацию», ст. 7
                </Word> Называет загранпаспорт основным документом, удостоверяющим личность гражданина РФ за пределами РФ.
                Это про <Word>
                    <Bold />
                    личность
                </Word>, а не прямо про <Word>
                    <Bold />
                    гражданство
                </Word>, поэтому как вспомогательный довод.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Что сказать, если спросят:
                </Word> «Согласно Положению, утверждённому Указом Президента РФ от 22.11.2023 № 889 (раздел XIV),
                гражданство РФ удостоверяется паспортом гражданина РФ, в том числе удостоверяющим личность за пределами
                территории РФ. Мой действующий загранпаспорт подтверждает моё гражданство».
            </Paragraph>
            <Paragraph>Sources:</Paragraph>
            <Paragraph>
                <List />
                <Line>
                    <Word>
                        <Reference>https://sfr.gov.ru/grazhdanam/semyam_s_detmi/materinskij_kapital/dokumenty_podtverzhdayushchie_grazhdanstvo_rf/</Reference>
                        СФР: документы, подтверждающие гражданство РФ
                    </Word>
                </Line>
                <Line>
                    <Word>
                        <Reference>https://www.consultant.ru/law/podborki/dokumenty_na_grazhdanstvo/</Reference>
                        КонсультантПлюс: документы на гражданство (раздел XIV Указа № 889)
                    </Word>
                </Line>
                <Line>
                    <Word>
                        <Reference>https://www.consultant.ru/document/cons_doc_LAW_363855/f72112b2137b827e9f06fa2a6fe645721544a707/</Reference>
                        КонсультантПлюс: ст. 7 114-ФЗ
                    </Word>
                </Line>
            </Paragraph>
        </Message>
