        <Message
            at="2026-10-09T08:08:18.679342Z"
        >
            <Origin>61de95c0-d2ee-472b-8f6e-b30046d53f27</Origin>
            <Speaker>$[[ Claude ]]( Dougs Claude )</Speaker>
            <Paragraph>Хороший вопрос, вы заметили непоследовательность. Логика такая:</Paragraph>
            <Paragraph>
                <List />
                <Line>
                    <Word>
                        <Bold />
                        Если смена произошла в конце месяца
                    </Word>, следующий период начинается со следующего месяца. Вы уволились 31.10.2016, поэтому «… –
                    10.2016» и «11.2016 – …», без пересечения.
                </Line>
                <Line>
                    <Word>
                        <Bold />
                        Если смена произошла в середине месяца
                    </Word>, этот месяц попадает в обе строки. Вы переехали в Слапи в июне 2025 года: часть июня вы жили в
                    Москве, часть в Слапи. Поэтому «… – 06.2025» и «06.2025 – …».
                </Line>
            </Paragraph>
            <Paragraph>
                Главное правило анкеты — <Word>
                    <Bold />
                    никаких пропусков
                </Word>. Пересечение в один месяц допустимо и встречается постоянно.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    И при проверке я нашёл у себя неточность.
                </Word> Самозанятость оформлена <Word>
                    <Bold />
                    20.04.2021
                </Word>, то есть в середине апреля. Значит, до 20 апреля вы ещё «не работали», и правильно так:
            </Paragraph>
            <Paragraph>
                <Quoted />
                <Word>
                    <Bold />
                    11.2016 – 04.2021
                </Word> — не работала, уход за детьми; адрес проживания: Россия, 117593, г. Москва, Литовский бульвар, д.
                19, кв. 92 <Word>
                    <Bold />
                    04.2021 – 12.2024
                </Word> — самозанятая (иллюстратор, картограф), работа удалённо; адрес проживания: Россия, 117593, г.
                Москва, Литовский бульвар, д. 19, кв. 92
            </Paragraph>
            <Paragraph>
                Замените в итоговом тексте «03.2021» на «04.2021». Остальные границы стоят правильно, если переезды были в
                середине месяца. Если какой-то переезд пришёлся ровно на конец месяца (например, в Турцию 30–31 декабря),
                можно оставить и так: на приём документов это не влияет.
            </Paragraph>
        </Message>
