        <Message
            at="2026-10-09T08:25:57.815642Z"
        >
            <Origin>783b9fb3-69f9-4699-87f0-a196415e2ce8</Origin>
            <Speaker>$[[ Claude ]]( Dougs Claude )</Speaker>
            <Paragraph>
                Здесь нет противоречия, обе фразы говорят об одном: <Word>
                    <Bold />
                    один документ = один PDF-файл
                </Word>.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Для внутреннего паспорта:
                </Word> все его развороты (фото, регистрация, семейное положение) <Word>
                    <Bold />
                    склейте в один многостраничный PDF
                </Word>. Это один документ, значит, один файл.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Нельзя наоборот:
                </Word> складывать <Word>
                    <Bold />
                    разные
                </Word> документы в один PDF, например паспорт и свидетельство о браке вместе.
            </Paragraph>
            <Paragraph>Итого у вас получится примерно так:</Paragraph>
            <Paragraph>
                <List />
                <Line>
                    <Word>
                        <Verbatim />
                        Загранпаспорт.pdf
                    </Word> — 1 страница;
                </Line>
                <Line>
                    <Word>
                        <Verbatim />
                        Паспорт РФ.pdf
                    </Word> — несколько страниц, все развороты внутреннего паспорта;
                </Line>
                <Line>
                    <Word>
                        <Verbatim />
                        Свидетельство о рождении.pdf
                    </Word>;
                </Line>
                <Line>
                    <Word>
                        <Verbatim />
                        Свидетельство (справка) о заключении брака.pdf
                    </Word>;
                </Line>
                <Line>
                    <Word>
                        <Verbatim />
                        Свидетельство о расторжении брака.pdf
                    </Word>.
                </Line>
            </Paragraph>
            <Paragraph>Каждый файл — отдельным вложением в одном ответном письме.</Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Про четвёртый скан паспорта.
                </Word> Запросили три разворота: с фото, с регистрацией и с семейным положением. Если четвёртый — это
                продолжение регистрации или другая страница с отметками, его можно добавить в тот же PDF, лишним не будет.
                Если это пустая страница, не нужно.
            </Paragraph>
            <Paragraph>
                <Word>
                    <Bold />
                    Как склеить безопасно, не загружая паспорт на чужие сайты:
                </Word>
            </Paragraph>
            <Paragraph>
                <List />
                <Line>
                    <Word>
                        <Bold />
                        Если у вас есть Adobe Acrobat:
                    </Word> «Инструменты → Объединить файлы», выбрать 4 файла по порядку, сохранить.
                </Line>
                <Line>
                    <Word>
                        <Bold />
                        Если сканы в формате картинок (JPG/PNG), в Windows:
                    </Word> выделите их в проводнике по порядку → правая кнопка → «Печать» → принтер <Word>
                        <Bold />
                        «Microsoft Print to PDF»
                    </Word> → снимите галочку «Подогнать изображение под размер кадра», если обрезает → «Печать» и
                    сохраните.
                </Line>
            </Paragraph>
            <Paragraph>Онлайн-сервисы для склейки PDF лучше не использовать: туда пришлось бы загружать паспорт.</Paragraph>
        </Message>
